#!/bin/sh
# Runs mail-starttls.sh from the mesa.black server (k3s spoke), where port 25
# is reachable, in a throwaway pod deleted at the end. From the workstation:
#   sh run-mail-starttls.sh
# Output lands in results/2026-10-16.mailtls.jsonl.
set -eu
cd "$(dirname "$0")"
kubectl --context mesa-black -n default run pq-mail-probe --rm -i --restart=Never --quiet \
    --image=docker.io/library/alpine:3.22 --command -- \
    sh -c 'apk add -q --no-cache openssl coreutils >/dev/null && echo  | base64 -d > /probe.sh && sh /probe.sh' \
    < results/2026-10-16.mx.txt > results/2026-10-16.mailtls.jsonl
wc -l results/2026-10-16.mailtls.jsonl
